import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";
import * as fs from "fs/promises";

async function main() {
  const trialIdRaw = (await fs.readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const normalizedTrialId = trialIdRaw.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
  const sourceBucketName = `harbor-isolation-${normalizedTrialId}`;

  const { forkSet, error } = await createForks(sourceBucketName, 3, {
    prefix: "audit-fork",
    credentials: { role: "Editor" },
  });

  if (error) {
    throw new Error(`Failed to create forks: ${error.message}`);
  }

  if (!forkSet) {
    throw new Error("forkSet is null");
  }

  try {
    const uploadPromises = forkSet.forks.map(async (fork, index) => {
      const client = new S3Client({
        region: "REDACTED",
        endpoint: "REDACTED",
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });

      const key = `agent-${index + 1}.out`;
      await client.send(
        new PutObjectCommand({
          Bucket: fork.bucket,
          Key: key,
          Body: `Content for ${key}`,
        })
      );
    });

    await Promise.all(uploadPromises);

    // Audit
    const adminClient = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
        secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
      },
    });

    const listSource = await adminClient.send(
      new ListObjectsV2Command({ Bucket: sourceBucketName })
    );
    const sourceKeys = (listSource.Contents || []).map((c) => c.Key!).sort();

    if (sourceKeys.length !== 2 || !sourceKeys.includes("seed1.txt") || !sourceKeys.includes("seed2.txt")) {
      throw new Error(`Source bucket does not contain exactly seed1.txt and seed2.txt. Found: ${sourceKeys.join(", ")}`);
    }

    const forkResults = [];

    for (let index = 0; index < forkSet.forks.length; index++) {
      const fork = forkSet.forks[index];
      const client = new S3Client({
        region: "REDACTED",
        endpoint: "REDACTED",
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });

      const listFork = await client.send(
        new ListObjectsV2Command({ Bucket: fork.bucket })
      );
      const forkKeys = (listFork.Contents || []).map((c) => c.Key!).sort();

      const expectedAgentKey = `agent-${index + 1}.out`;
      const expectedKeys = ["seed1.txt", "seed2.txt", expectedAgentKey].sort();

      if (forkKeys.length !== 3) {
        throw new Error(`Fork ${fork.bucket} does not contain exactly 3 objects. Found: ${forkKeys.join(", ")}`);
      }

      for (const expectedKey of expectedKeys) {
        if (!forkKeys.includes(expectedKey)) {
          throw new Error(`Fork ${fork.bucket} is missing expected key ${expectedKey}. Found: ${forkKeys.join(", ")}`);
        }
      }

      // Check it doesn't contain another fork's key
      for (let j = 0; j < forkSet.forks.length; j++) {
        if (j !== index) {
          const otherAgentKey = `agent-${j + 1}.out`;
          if (forkKeys.includes(otherAgentKey)) {
            throw new Error(`Fork ${fork.bucket} contains another fork's key ${otherAgentKey}.`);
          }
        }
      }

      forkResults.push({
        bucket: fork.bucket,
        keys: forkKeys,
      });
    }

    const auditReport = {
      source_keys: sourceKeys,
      fork_results: forkResults,
    };

    await fs.writeFile("/home/user/isolation/audit.json", JSON.stringify(auditReport, null, 2), "utf-8");

  } finally {
    const teardownResult = await teardownForks(forkSet);
    if (teardownResult.error) {
      console.error(`Failed to teardown forks: ${teardownResult.error.message}`);
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

