import { S3Client, CreateBucketCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import * as fs from "fs/promises";
import { execSync } from "child_process";

async function run() {
  const trialIdRaw = (await fs.readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const normalizedTrialId = trialIdRaw.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
  const bucket = `harbor-isolation-${normalizedTrialId}`;

  const client = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  try {
    await client.send(new CreateBucketCommand({ Bucket: bucket }));
  } catch (e: any) {
    if (e.name !== "BucketAlreadyOwnedByYou" && e.name !== "BucketAlreadyExists") {
      throw e;
    }
  }

  // enable snapshots using tigris cli
  execSync(`/home/user/isolation/node_modules/.bin/tigris snapshots enable ${bucket}`);

  await client.send(new PutObjectCommand({ Bucket: bucket, Key: "seed1.txt", Body: "seed1" }));
  await client.send(new PutObjectCommand({ Bucket: bucket, Key: "seed2.txt", Body: "seed2" }));
  console.log("Setup done");
}
run();
EOF
cd /home/user/isolation && npx tsx test-setup.ts

